values ('phq9', 'PHQ-9', 'Patient Health Questionnaire (PHQ-9)', null, 'Over the last 2 weeks, how often have you been bothered by any of the following problems?', null,
  '[{"id":"q1","text":"Little interest or pleasure in doing things","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q2","text":"Feeling down, depressed, or hopeless","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q3","text":"Trouble falling or staying asleep, or sleeping too much","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q4","text":"Feeling tired or having little energy","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q5","text":"Poor appetite or overeating","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q6","text":"Feeling bad about yourself, or that you are a failure or have let yourself or your family down","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q7","text":"Trouble concentrating on things, such as reading the newspaper or watching television","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q8","text":"Moving or speaking so slowly that other people could have noticed, or the opposite: being so fidgety or restless that you have been moving around a lot more than usual","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]},{"id":"q9","text":"Thoughts that you would be better off dead, or of hurting yourself in some way","options":[{"label":"Not at all","value":0},{"label":"Several days","value":1},{"label":"More than half the days","value":2},{"label":"Nearly every day","value":3}]}]'::jsonb,
  '[{"min":0,"max":4,"label":"Minimal","level":0},{"min":5,"max":9,"label":"Mild","level":1},{"min":10,"max":14,"label":"Moderate","level":2},{"min":15,"max":19,"label":"Moderately severe","level":3},{"min":20,"max":27,"label":"Severe","level":4}]'::jsonb, '{q9}', true)
on conflict (id) do update set code = excluded.code, title = excluded.title, instructions = excluded.instructions,
