insert into public.templates (owner_id, shared, kind, title, body, locale, form_id)
select null, true, 'message', 'Welcome', 'Welcome to New Chester Clinic. I''m looking forward to our first session. If anything comes up before then, message me here.', 'en', null
where not exists (select 1 from public.templates where shared and owner_id is null and title = 'Welcome');

